/* LynkOmni Account rules in TypeScript (build section 2): the same rules as identity/account.py and identity/auth.py in Python,
 * proved against the shared vectors in contract/vectors/account.v1.json (generated by tools/account_vectors.py). The account site
 * and the apps call these; the cloud is the authority and a device never decides a sign-in, a recovery or a consent on its own. */

export const DAY = 86400;
export const SIGN_UP_STEPS = ["username", "contact", "passkey", "recovery_code"] as const;
export type SignUpStep = (typeof SIGN_UP_STEPS)[number];
export interface SignUpState { username?: string; adult?: boolean; contactVerified?: boolean; passkey?: boolean; recoveryCodeConfirmed?: boolean }
/** The next thing to do, or null when the account exists. The order is fixed: a recovery code is only shown once a passkey exists. */
export function nextSignUpStep(s: SignUpState): SignUpStep | null {
  if (!s.username || s.adult !== true) return "username";   // the first step also confirms the minimum age (18 or the local age of majority); no birth date is asked
  if (!s.contactVerified) return "contact";
  if (!s.passkey) return "passkey";
  if (!s.recoveryCodeConfirmed) return "recovery_code";
  return null;
}

// ---- recovery (blueprint section 10, inside section 22): strongest path first, SMS never enough on its own
export type RecoveryPath = "device" | "code" | "assisted";
export const RECOVERY: Record<RecoveryPath, { waitS: number; approvals: number; needs: string[] }> = {
  device: { waitS: 0, approvals: 0, needs: ["other_enrolled_owner_device", "its_pin"] },
  code: { waitS: 24 * 3600, approvals: 0, needs: ["recovery_code", "sms_code"] },
  assisted: { waitS: 72 * 3600, approvals: 2, needs: ["id_document", "business_proof", "live_check"] },
};
export const NEVER_ALLOWED = ["sms_only", "security_questions", "phone_call_reset", "email_only"] as const;
export const RESTRICTED_AFTER_RECOVERY = ["change_role", "change_payout", "revoke_device", "export_data"] as const;
export const RESTRICTION_S = DAY;   // 24 hours
/** Which path a person can take, strongest first. */
export function recoveryPath(o: { otherDevice: boolean; recoveryCode: boolean; smsOk: boolean }): RecoveryPath {
  if (o.otherDevice) return "device";
  if (o.recoveryCode && o.smsOk) return "code";
  return "assisted";
}
export interface RecoveryState { path: RecoveryPath; startedAt: number; approvals: number; cancelled?: boolean }
export function recoveryReady(r: RecoveryState, now: number): boolean {
  const p = RECOVERY[r.path];
  return !r.cancelled && now >= r.startedAt + p.waitS && r.approvals >= p.approvals;
}
export const recoveryReadyAt = (r: RecoveryState): number => r.startedAt + RECOVERY[r.path].waitS;
/** After any recovery the new device is restricted for a day: no role or payout changes, no revoking other devices, no export. */
export function deviceCan(action: string, restrictedUntil: number, now: number): boolean {
  return !((RESTRICTED_AFTER_RECOVERY as readonly string[]).includes(action) && now < restrictedUntil);
}

// ---- sessions: bound to one site, 12 hours, step-up for sensitive actions
export const SITES = ["account", "bookings", "essentials", "exchange", "merchant"] as const;
export type Site = (typeof SITES)[number];
export const SESSION_S = 12 * 3600;
export const STEPUP_S = 600;
export interface Session { site: Site; expires: number }
export const sessionValid = (s: Session, site: Site, now: number): boolean => s.site === site && s.expires > now;
/** A sign-in from a device or place not seen before (and not the very first sign-in) sends an alert with no link in it. */
export function signInAlertNeeded(seen: { device: string; place: string }[], device: string, place: string): { alert: boolean; newDevice: boolean; newPlace: boolean } {
  const newDevice = seen.length > 0 && !seen.some((x) => x.device === device);
  const newPlace = seen.length > 0 && !seen.some((x) => x.place === place);
  return { alert: newDevice || newPlace, newDevice, newPlace };
}

// ---- takeover safeguards (blueprint 43 H)
export const PAYOUT_WAIT_S = DAY;   // 24 hours
export function payoutChange(secondDeviceOk: boolean, now: number): { status: "applied" | "waiting"; readyAt: number } {
  return secondDeviceOk ? { status: "applied", readyAt: now } : { status: "waiting", readyAt: now + PAYOUT_WAIT_S };
}
export const exportAllowed = (stepUpValid: boolean, restrictedUntil: number, now: number): boolean => stepUpValid && deviceCan("export_data", restrictedUntil, now);

// ---- data-sharing consents: a scope, a purpose, an end
export const CONSENT_SCOPES = ["health-pack", "accountant", "lender", "developer-app", "support", "supplier-sell-through", "location-share"] as const;
export type ConsentScope = (typeof CONSENT_SCOPES)[number];
export const MAX_CONSENT_DAYS: Record<ConsentScope, number> = { "health-pack": 90, accountant: 365, lender: 30, "developer-app": 365, support: 1, "supplier-sell-through": 365, "location-share": 30 };
export const CONSENT_WARN_DAYS = 7;
export function consentEnd(scope: ConsentScope, days: number, now: number): number { return now + Math.min(Math.max(1, Math.floor(days)), MAX_CONSENT_DAYS[scope]) * DAY; }
export interface Consent { scope: ConsentScope; grantee: string; purpose: string; expires: number; withdrawn?: number }
export type ConsentState = "active" | "ending_soon" | "ended" | "withdrawn";
export function consentState(c: Consent, now: number): ConsentState {
  if (c.withdrawn) return "withdrawn";
  if (c.expires <= now) return "ended";
  return c.expires - now <= CONSENT_WARN_DAYS * DAY ? "ending_soon" : "active";
}

// ---- privacy and data
export const DATA_REQUEST_DAYS = 30;
export const DATA_READY_DAYS = 7;
export const CLOSE_GRACE_DAYS = 30;
export const dataRequestDue = (now: number): number => now + DATA_REQUEST_DAYS * DAY;
export const closesAt = (now: number): number => now + CLOSE_GRACE_DAYS * DAY;

// ---- N4 standing payments: the customer's own capped instruction, held by the licensed provider, told every time
export function standingChargeAllowed(capMinor: number, amountMinor: number, revoked: boolean, providerReady: boolean): boolean {
  return providerReady && !revoked && amountMinor > 0 && amountMinor <= capMinor;
}

// ---- N14 Start a business
export const REGISTRATION_STEPS = ["profile", "registration", "tax_number", "bank_account"] as const;
export type RegistrationStep = (typeof REGISTRATION_STEPS)[number];
export type ApplicationStatus = "started" | "submitted" | "approved" | "rejected";
export const canSubmit = (steps: Record<RegistrationStep, boolean>): boolean => steps.profile && steps.registration && steps.tax_number;
/** The status only ever moves on the gateway's answer: LynkOmni never shows "approved" before the authority says so. */
export function applicationStatus(current: ApplicationStatus, gateway: "pending" | "approved" | "rejected" | null): ApplicationStatus {
  if (current !== "submitted" || !gateway || gateway === "pending") return current;
  return gateway;
}

// ---- the account site
export const PAGES = ["overview", "profile", "security", "businesses", "orders", "transactions", "wallet", "billing", "memberships", "privacy", "notifications", "messages", "support", "assist", "payslips", "payments", "start", "storefront", "trips", "collect"] as const;
export type Page = (typeof PAGES)[number];
export const pagePath = (p: Page): string => (p === "overview" ? "/" : `/${p}`);
/** Security Center rows: event type to the string key the screen shows (the word, never colour alone, beside the time). */
export const SECURITY_EVENT_KEY: Record<string, string> = {
  SessionStarted: "ev_session_started", SessionRevoked: "ev_session_revoked", PasskeyEnrolled: "ev_passkey_enrolled", PasskeyRevoked: "ev_passkey_revoked",
  RecoveryStarted: "ev_recovery_started", RecoveryCompleted: "ev_recovery_completed", RecoveryCancelled: "ev_recovery_cancelled",
  PayoutChangeRequested: "ev_payout_requested", PayoutChangeApplied: "ev_payout_applied", ConsentGranted: "ev_consent_granted", ConsentWithdrawn: "ev_consent_withdrawn", SecurityAlertSent: "ev_alert_sent",
};
